begin;
savepoint management_fixtures;
do $$
declare dr record; administrator uuid; quote uuid:=gen_random_uuid(); request uuid:=gen_random_uuid(); token text:=encode(gen_random_bytes(32),'hex'); tariff uuid; rate integer; pickup timestamptz; candidate timestamptz; later_time timestamptz; result jsonb; b bookings; n integer; rejected boolean; block_id uuid; original_count integer;
begin
 select d.id,d.vehicle_id into dr from drivers d join vehicles v on v.id=d.vehicle_id where d.active and v.active order by d.id limit 1;
 select id into administrator from profiles where role in('business_admin','technical_admin') limit 1;
 if dr.id is null or administrator is null then raise exception 'Missing configured test roles';end if;
 perform set_config('request.jwt.claim.sub','',true);
 rejected:=false;begin perform set_tariff(2500,null);exception when raise_exception then rejected:=true;end;if not rejected then raise exception 'Anonymous tariff modification accepted';end if;
 for n in 1..5760 loop candidate:=date_trunc('hour',now())+make_interval(mins=>n*15);if test_slot_available(dr.id,dr.vehicle_id,candidate,30) then pickup:=candidate;exit;end if;end loop;
 if pickup is null then raise exception 'No fixture time';end if;
 select id,per_km_cop into tariff,rate from tariff_versions order by effective_from desc limit 1;
 insert into route_quotes values(quote,'[{"label":"Recogida de prueba","original":"Referencia original","lon":-76.5510361,"lat":3.45827658},{"label":"Llegada de prueba","original":"Destino original","lon":-76.5462561,"lat":3.42465042}]',6000,1800,rate*6,tariff,now()+interval '15 minutes');
 result:=submit_quoted_booking(request,token,quote,jsonb_build_object('first_name','Comprobación transaccional','phone','+573001234567','passengers',1,'pets',true,'luggage',false,'pickup_at',pickup,'consent',true,'whatsapp_consent',true,'payment_method','efectivo'));
 if result->>'ok'<>'true' then raise exception 'Cash reservation rejected';end if;
 select * into b from bookings where request_id=request;
 if b.payment_method<>'efectivo' or b.price_cop<>rate*6 or not b.whatsapp_consent then raise exception 'Reservation fields lost';end if;
 if not exists(select 1 from notification_outbox where booking_id=b.id and channel='whatsapp' and payload->>'audience'='customer' and delivered_at is null and attempts=0) then raise exception 'Customer notification not queued';end if;
 result:=submit_quoted_booking(request,token,quote,'{}');if result->>'reference'<>b.reference then raise exception 'Idempotency failed';end if;
 perform set_config('request.jwt.claim.sub',dr.id::text,true);
 rejected:=false;begin perform set_personal_block(dr.id,pickup,pickup+interval '1 hour','Conflicto de prueba');exception when raise_exception then rejected:=true;end;if not rejected then raise exception 'Overlapping manual block accepted';end if;
 rejected:=false;begin perform mark_booking_paid(b.id);exception when raise_exception then rejected:=true;end;if not rejected then raise exception 'Unfinished trip marked paid';end if;
 perform set_config('request.jwt.claim.sub','',true);
 for n in 1..5760 loop candidate:=pickup+make_interval(mins=>n*15);if test_slot_available(dr.id,dr.vehicle_id,candidate,30) then later_time:=candidate;exit;end if;end loop;
 result:=reschedule_booking(b.reference,token,later_time);if result->>'ok'<>'true' then raise exception 'Reschedule failed';end if;
 if not exists(select 1 from bookings where id=b.id and pickup_at=later_time and status='pending_driver') then raise exception 'Reschedule not persisted';end if;
 perform set_config('request.jwt.claim.sub',dr.id::text,true);
 block_id:=set_personal_block(dr.id,pickup,pickup+interval '15 minutes','Descanso de prueba');perform remove_personal_block(block_id);if exists(select 1 from calendar_slots where id=block_id and active) then raise exception 'Block not released';end if;
 update bookings set status='completed' where id=b.id;perform mark_booking_paid(b.id);
 if not exists(select 1 from bookings where id=b.id and payment_status='paid') then raise exception 'Payment not registered';end if;
 perform set_config('request.jwt.claim.sub',administrator::text,true);perform set_tariff(rate+1,null);
 if (select tariff_id from bookings where id=b.id)<>tariff then raise exception 'Existing booking tariff changed';end if;
 perform update_site_settings('Título verificado','Mensaje de bienvenida verificado','Aviso de reserva verificado');if get_public_settings()->>'welcome_title'<>'Título verificado' then raise exception 'Settings not persisted';end if;
 perform set_config('request.jwt.claim.sub','',true);
end $$;
rollback to savepoint management_fixtures;
release savepoint management_fixtures;
commit;
